#include <iostream>
#include <string>
#include <vector>

struct Registro {
    std::string codigo;
    int unidades;
};

int main() {
    Registro original{"R4", 6};
    std::cout << original.codigo << ":" << original.unidades << "\n";
    Registro copia = original;
    original.unidades += 3;
    std::cout << "Original " << original.codigo << ":" << original.unidades << "\n";
    std::cout << "Copie " << copia.codigo << ":" << copia.unidades;
    return 0;
}

#include <iostream>
#include <string>
#include <vector>

struct Lectura {
    std::string sitio;
    int personas;
};

int doble(int cantidad) {
    return cantidad * 2;
}

int main() {
    Lectura registro{"Est", 4};
    int total = doble(registro.personas);
    std::cout << registro.personas << " " << total;
    return 0;
}
